mapper.select:
select r.report_id as reportId, r.period_id as periodId, r.emp_id as empId, r.avg_performance as avgPerformance, r.avg_expertise as avgExpertise, r.avg_teamwork as avgTeamwork, r.avg_attitude as avgAttitude, r.avg_growth as avgGrowth, r.overall_score as overallScore, r.grade as grade, r.sentiment_positive as sentimentPositive, r.sentiment_neutral as sentimentNeutral, r.sentiment_negative as sentimentNegative, r.sentiment_label as sentimentLabel, r.model_name as modelName, r.att_work_days as attWorkDays, r.att_late_count as attLateCount, r.att_early_leave_count as attEarlyLeaveCount, r.att_absent_count as attAbsentCount, r.att_annual_used as attAnnualUsed, r.att_total_work_min as attTotalWorkMin, r.att_overtime_min as attOvertimeMin, r.att_rate as attRate, TO_CHAR(r.generated_at, 'YYYY-MM-DD HH24:MI') as generatedAt, p.title as periodTitle, p.eval_year as periodYear, p.eval_term as periodTerm, emp.emp_name as empName, emp.emp_no as empNo, dept.dept_name as deptName, pos.pos_name as posName from evaluation_ai_report r join evaluation_period p on r.period_id = p.period_id join employee emp on r.emp_id = emp.emp_id join department dept on emp.dept_id = dept.dept_id join emp_position pos on emp.pos_id = pos.pos_id
r.period_id = #{periodId} and p.com_id = #{comId}
and emp.dept_id = #{deptId}
and (emp.emp_name like '%' || #{keyword} || '%' or emp.emp_no like '%' || #{keyword} || '%')
order by r.overall_score desc, pos.pos_order, emp.emp_no offset #{pstartno} rows fetch next #{onepagelist} rows only

select count(*) from evaluation_ai_report r join evaluation_period p on r.period_id = p.period_id join employee emp on r.emp_id = emp.emp_id
r.period_id = #{periodId} and p.com_id = #{comId}
and emp.dept_id = #{deptId}
and (emp.emp_name like '%' || #{keyword} || '%' or emp.emp_no like '%' || #{keyword} || '%')
